const https = require('https');
const fs = require('fs');
const path = require('path');

async function getCertificateExpiry(host, port = 443) {
  return new Promise((resolve, reject) => {
    const opts = { host, port, method: 'GET', rejectUnauthorized: true };
    const req = https.request(opts, (res) => {
      const cert = res.socket.getPeerCertificate();
      const expiry = new Date(cert.valid_to);
      resolve({ host, expiry, daysUntilExpiry: Math.ceil((expiry - Date.now()) / 86400000) });
    });
    req.on('error', reject);
    req.end();
  });
}

