+// GraphQL DataLoader for batched and cached query resolution (N+1 prevention)
+class DataLoader {
+  constructor(batchLoadFn, opts = {}) {
+    this.batchLoadFn = batchLoadFn;
+    this.cacheKeyFn = opts.cacheKeyFn || ((k) => k);
+    this.cache = new Map();
+    this.pending = new Map();
+    this.maxBatchSize = opts.maxBatchSize || 100;
+  }
+
+  load(key) {
+    const cacheKey = this.cacheKeyFn(key);
+    if (this.cache.has(cacheKey)) return Promise.resolve(this.cache.get(cacheKey));
+    if (!this.pending.has(cacheKey)) {
+      const promise = this.batchLoadFn([key]).then((results) => {
+        this.cache.set(cacheKey, results[0]);
+        this.pending.delete(cacheKey);
+        return results[0];
+      });
+      this.pending.set(cacheKey, promise);
+    }
+    return this.pending.get(cacheKey);
+  }
+
+  loadMany(keys) {
+    return Promise.all(keys.map(k => this.load(k)));
+  }
+
+  clear(key) { this.cache.delete(this.cacheKeyFn(key)); return this; }
+  clearAll() { this.cache.clear(); return this; }
+}
+
+module.exports = { DataLoader };

